function JesusCompareScreen({ state, onBack }) {
  const [selA, setSelA] = useState(null);
  const [selB, setSelB] = useState(null);

  const handleSelect = (id) => {
    if (selA === id) { setSelA(null); return; }
    if (selB === id) { setSelB(null); return; }
    if (!selA) { setSelA(id); return; }
    if (!selB) { setSelB(id); return; }
    setSelA(selB); setSelB(id);
  };

  const pA = JESUS_PORTRAITS.find(p => p.id === selA);
  const pB = JESUS_PORTRAITS.find(p => p.id === selB);
  const bothSelected = pA && pB;

  return (
    <div className={`screen ${state}`}>
      <div className="inner-screen">
        <button className="back-btn" onClick={onBack}>← Back</button>
        <div className="gc-header">
          <div className="inner-header-eyebrow">Scholarly Portraits</div>
          <div className="inner-header-title">Compare</div>
          <div className="inner-header-rule" />
          <div className="gc-instruction">
            {!selA && !selB && "Pick two portraits to compare"}
            {selA && !selB && "Now pick a second portrait"}
            {bothSelected && "Scroll to see how they differ"}
          </div>
        </div>
        <div className="jc-picker">
          {JESUS_PORTRAITS.map(p => {
            const isA = selA === p.id;
            const isB = selB === p.id;
            return (
              <button key={p.id} className={`jc-portrait-btn ${isA ? "sel-a" : ""} ${isB ? "sel-b" : ""}`} onClick={() => handleSelect(p.id)}>
                <div className="jc-icon"><div className={`jc-icon-bg ${p.bgClass}`} /></div>
                <div className="jc-label">{p.title}</div>
                <div className="jc-scholar">{p.scholar}</div>
                {isA && <div className="gc-badge gc-badge-a">A</div>}
                {isB && <div className="gc-badge gc-badge-b">B</div>}
              </button>
            );
          })}
        </div>
        <div className="gc-divider" />
        <div className="gc-compare-area">
          {!bothSelected ? (
            <div className="gc-empty">
              <div className="gc-empty-icon">⚖</div>
              <div className="gc-empty-text">Select two scholarly portraits above<br />to see how they differ on the same questions</div>
            </div>
          ) : (
            <>
              <div className="gc-col-headers">
                <div className="gc-col-hdr gc-col-hdr-a">
                  <div className="gc-col-title gc-col-title-a">{pA.title}</div>
                  <div className="gc-col-subtitle">{pA.scholar}</div>
                </div>
                <div className="gc-col-hdr gc-col-hdr-b">
                  <div className="gc-col-title gc-col-title-b">{pB.title}</div>
                  <div className="gc-col-subtitle">{pB.scholar}</div>
                </div>
              </div>
              {JESUS_QUESTIONS.map(q => (
                <div key={q.id} className="gc-question">
                  <div className="gc-q-label">{q.label}</div>
                  <div className="gc-answers">
                    <div className="gc-answer gc-answer-a">{pA.answers[q.id]}</div>
                    <div className="gc-answer gc-answer-b">{pB.answers[q.id]}</div>
                  </div>
                </div>
              ))}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

