const SCREENS = ["home","gospels","canonical","mark","matthew","john","gospel-compare","q-source","jesus","jesus-quests","jesus-portraits","jesus-compare","paul","christophany","who-wrote-mark","when-was-mark","messianic-secret","christology-mark","temple-prediction"];

export default function App() {
  const [history, setHistory] = useState(["home"]);
  const [comparePreselect, setComparePreselect] = useState(null);
  const current = history[history.length - 1];

  const navigate = (screen) => setHistory(h => [...h, screen]);
  const goBack = () => setHistory(h => h.length > 1 ? h.slice(0, -1) : h);
  const openCompare = (gospelId) => { setComparePreselect(gospelId); navigate("gospel-compare"); };
  const stateFor = (screenId) => {
    if (screenId === current) return "active";
    const si = SCREENS.indexOf(screenId);
    const curI = SCREENS.indexOf(current);
    return si < curI ? "left" : "right";
  };

  return (
    <>
      <style>{styles}</style>
      <div className="app">
        <HomeScreen             state={stateFor("home")}           onNavigate={navigate} />
        <GospelsScreen          state={stateFor("gospels")}        onBack={goBack} onNavigate={navigate} />
        <CanonicalGospelsScreen state={stateFor("canonical")}      onBack={goBack} onNavigate={navigate} />
        <GospelTopicsScreen     state={stateFor("mark")}           onBack={goBack} eyebrow="The First Gospel"     title="The Gospel of Mark"    tiles={MARK_TILES}    gospelId="mark"    onCompare={openCompare} onNavigate={navigate} />
        <GospelTopicsScreen     state={stateFor("matthew")}        onBack={goBack} eyebrow="The Matthean Gospel"  title="The Gospel of Matthew" tiles={MATTHEW_TILES} gospelId="matthew" onCompare={openCompare} />
        <GospelTopicsScreen     state={stateFor("john")}           onBack={goBack} eyebrow="The Johannine Gospel" title="The Gospel of John"    tiles={JOHN_TILES}    gospelId="john"    onCompare={openCompare} />
        <GospelCompareScreen    state={stateFor("gospel-compare")} onBack={goBack} preselectedId={comparePreselect} />
        <QSourceScreen          state={stateFor("q-source")}       onBack={goBack} />
        <HistoricalJesusScreen  state={stateFor("jesus")}          onBack={goBack} onNavigate={navigate} />
        <JesusQuestsScreen      state={stateFor("jesus-quests")}   onBack={goBack} />
        <JesusPortraitsScreen   state={stateFor("jesus-portraits")} onBack={goBack} onNavigate={navigate} />
        <JesusCompareScreen     state={stateFor("jesus-compare")}  onBack={goBack} />
        <PaulScreen             state={stateFor("paul")}           onBack={goBack} onNavigate={navigate} />
        <ChristophanyScreen     state={stateFor("christophany")}   onBack={goBack} />
        <WhoWroteMarkScreen     state={stateFor("who-wrote-mark")}    onBack={goBack} />
        <WhenWasMarkScreen      state={stateFor("when-was-mark")}     onBack={goBack} />
        <MessianicSecretScreen   state={stateFor("messianic-secret")}  onBack={goBack} />
        <ChristologyOfMarkScreen  state={stateFor("christology-mark")}   onBack={goBack} />
        <DidJesusPredictScreen   state={stateFor("temple-prediction")}   onBack={goBack} />
      </div>
    </>
  );
}
